1	{
2	  "name": "norfinder",
3	  "private": true,
4	  "version": "0.10928.2"
5	}
6

1	// The dispatch issue — how a due (task, slot) becomes exactly-once, bounded,
2	// recoverable agent work. This module is the
3	// PURE half: issue identity (title/body/parse) and the create / skip / suppress
4	// decision over the issues that already exist. A thin scheduler shell does the
5	// GitHub I/O (search state=all, create, label, comment) and applies the verdict
6	// — the "should I file this" decision is always code here, never the shell's
7	// judgment (the same split the fleet planner uses).
8	//
9	// All behavior-defining content (agent_model, expected_outcome, agent_instructions) is read from the
10	// tracked task files, never from the issue — the body only points at the task
11	// file and carries the precondition's binding Context.
12	import { NEEDS_HUMAN } from '../../public/task-constants.mjs';
13	
14	
15	// The labels this machinery drives. `ready-for-agent` is what the executor
16	// routine fires on; `needs-human` is the single triage state every anomaly
17	// converges to. Kept here as the shared source for the
18	// scheduler side; the executor reuses these plus `agent-running`.
19	export const READY_LABEL = 'ready-for-agent';
20	// Fleet-scoped work dispatches to a DISTINCT ready label so a separate,
21	// broader-scoped executor routine runs it - keeping the fleet-wide session grant
22	// off every ordinary project's self executor (the per-project-scheduling fleet/self
23	// split).
24	export const READY_FLEET_LABEL = 'ready-for-agent-fleet';
25	export const AGENT_RUNNING_LABEL = 'agent-running';
26	export { NEEDS_HUMAN };
27	export const WORKFLOW_FAILURE_LABEL = 'workflow-failure';
28	
29	// WHICH EXECUTOR ROUTINE a session is. Not a property of a task - nothing asks a
30	// task what its reach is (a task needing more than its own repo names an
31	// `invocation_endpoint`) - but of the routine that is running: an ordinary
32	// project's executor is `self`, the broader-scoped fleet routine is `fleet`, and
33	// each picks up only what is filed under its own ready label.
34	export const EXECUTOR_SCOPES = ['self', 'fleet'];
35	
36	// The ready label a dispatch is filed under, from the scope of the executor meant
37	// to run it ('self' default → READY_LABEL; 'fleet' → READY_FLEET_LABEL). The one
38	// place this mapping lives, so the scheduler (which files) and any reader stay in
39	// sync.
40	export const readyLabelForScope = (scope) => (scope === 'fleet' ? READY_FLEET_LABEL : READY_LABEL);
41	
42	// The full label set the scheduler + executor drive, each with the colour and
43	// description a bootstrap one-off would have given it. The scheduler ENSURES every
44	// one exists (create-if-missing, idempotent) right before it dispatches — so there
45	// is no separate label-creation step to run or forget, and a deleted label
46	// self-heals on the next run. This is load-bearing, not cosmetic: GitHub does not
47	// create a label when you apply it (the issues API 422s on an unknown label), so
48	// the thing that assigns a label must guarantee it first — the
49	// gha/label-create-before-add principle, enforced in code here.
50	export const SCHEDULER_LABELS = [
51	  { name: READY_LABEL, color: '0e8a16', description: 'Claudinite scheduler: dispatch issue ready for the (self-scoped) executor to run' },
52	  { name: READY_FLEET_LABEL, color: '1d76db', description: 'Claudinite scheduler: dispatch ready for the FLEET-scoped executor (a task reaching other repos)' },
53	  { name: AGENT_RUNNING_LABEL, color: 'fbca04', description: 'Claudinite scheduler: the executor has claimed this issue and is running it' },
54	  { name: NEEDS_HUMAN, color: 'd93f0b', description: 'Claudinite scheduler: an anomaly that converged here for human triage' },
55	  { name: WORKFLOW_FAILURE_LABEL, color: 'b60205', description: 'Claudinite scheduler: a scheduler run or task failed' },
56	];
57	
58	// The escalation code as a LABEL, so "which condition woke the agent" is countable
59	// rather than only readable. The body already names the code, but a body is prose:
60	// counting it across a fleet means fetching and parsing every dispatch issue, while a
61	// label is a search facet (`label:escalation:checks-not-green`) any repo-set query can
62	// aggregate - which is what sizing the versioned-updates pack-apply stage needs (#768).
63	//
64	// DERIVED from the code the worker fired, never a list of codes kept here: the codes
65	// live in the code-work worker that raises them (a pack), the engine may not import a
66	// pack, and a hand-maintained copy of an enum on the other side of that barrier is
67	// exactly the drift the corpus forbids. So the label is minted per code, and the
68	// scheduler ensures it right before applying it — the same create-before-add
69	// discipline SCHEDULER_LABELS documents. A code that is not a plain kebab-case token
70	// gets no label (GitHub would take almost anything as a name, and a label built from
71	// a malformed code is a category nobody can query); the body still carries it.
72	export const ESCALATION_LABEL_PREFIX = 'escalation:';
73	export function escalationLabel(code) {
74	  if (typeof code !== 'string' || !/^[a-z0-9]+(-[a-z0-9]+)*$/.test(code)) return null;
75	  return {
76	    name: `${ESCALATION_LABEL_PREFIX}${code}`,
77	    color: '5319e7',
78	    description: `Claudinite scheduler: code_work escalated on "${code}"`,
79	  };
80	}
81	
82	// Title: `[claudinite-task] <pack>/<task> <slot-id>`. The prefix is
83	// what keeps these issues invisible to the scheduler's own signals (self-trigger
84	// exclusion) and searchable as a family.
85	export const DISPATCH_PREFIX = '[claudinite-task]';
86	
87	export const dispatchTitle = ({ pack, task, slotId }) => `${DISPATCH_PREFIX} ${pack}/${task} ${slotId}`;
88	
89	// The (pack, task) family key — every slot's title for one task starts with
90	// `<key> ` (the trailing space before the slot id is load-bearing: it stops
91	// `foo/extract` from matching `foo/extract-more`).
92	export const dispatchTaskKey = ({ pack, task }) => `${DISPATCH_PREFIX} ${pack}/${task}`;
93	
94	// pack and task ids are single path segments (no slash, no space); the slot id
95	// is the trailing non-space token.
96	const DISPATCH_TITLE_RE = /^\[claudinite-task\]\s+([^/\s]+)\/([^/\s]+)\s+(\S+)$/;
97	
98	export function parseDispatchTitle(title) {
99	  const m = DISPATCH_TITLE_RE.exec(String(title ?? '').trim());
100	  return m ? { pack: m[1], task: m[2], slotId: m[3] } : null;
101	}
102	
103	// Is this a scheduler dispatch issue? The self-trigger exclusion the signal
104	// collectors apply so the scheduler never sees its own dispatch issues as work.
105	export const isDispatchTitle = (title) => parseDispatchTitle(title) !== null;
106	
107	// The `### Delivered` section — what this run's code-work created, by identity. It is
108	// the agent's only source for those artifacts.
109	//
110	// Absence is meaningful: no section means code-work created nothing, so never write a
111	// placeholder here.
112	export function deliveredLines(delivered) {
113	  const { branch = null, pr = null, merged = false } = delivered ?? {};
114	  if (!branch && !pr) return [];
115	  return [
116	    '### Delivered by code-work',
117	    'The artifacts this run created — the ones to work on.',
118	    '',
119	    ...(pr ? [`- PR: #${pr}${merged ? ' (already merged — open your own PR for further work)' : ' (open)'}`] : []),
120	    ...(branch ? [`- Branch: \`${branch}\``] : []),
121	  ];
122	}
123	
124	// The `### Why the agent is here` section — which of code-work's escalation
125	// conditions fired. The worker knows it exactly; without this the agent re-derives it
126	// from the repo, and a re-derivation that disagrees with the truth is how a run ends up
127	// reporting "code-work created nothing" about a cycle that just merged a PR
128	// (EdFringeAllocator#82).
129	//
130	// The condition and its counts, never the findings - those stay in the repo.
131	// Absence is meaningful here too: a worker too old to name a reason says nothing, and
132	// the agent falls back to its task file's own sweep.
133	export function escalationLines(reason) {
134	  const { code = null, detail = null } = reason ?? {};
135	  if (!code && !detail) return [];
136	  return [
137	    '### Why the agent is here',
138	    'The condition code_work escalated on. Start here; the findings themselves are in the repo, not this issue.',
139	    '',
140	    `- ${detail || code}${detail && code ? ` (\`${code}\`)` : ''}`,
141	  ];
142	}
143	
144	// The dispatch issue body. First line is the task-file path - the only thing the
145	// executor reads to locate the worker; everything below is human framing plus the
146	// precondition's binding Context. The Context block is emitted only when the
147	// precondition produced lines (an empty scope has nothing to bind).
148	export function dispatchBody({ taskPath, pack, task, slotId, context = [], delivered = null, reason = null }) {
149	  const lines = [taskPath, ''];
150	  if (context.length) {
151	    lines.push(
152	      `Execute the Claudinite task above (pack \`${pack}\`, task \`${task}\`, slot \`${slotId}\`).`,
153	      'The Context section below is binding scope — do not re-decide it.',
154	      '',
155	      '### Context',
156	    );
157	    for (const c of context) lines.push(`- ${c}`);
158	  } else {
159	    lines.push(`Execute the Claudinite task above (pack \`${pack}\`, task \`${task}\`, slot \`${slotId}\`).`);
160	  }
161	  // Why first, then what: the reason is what decides which of the task file's sections
162	  // the agent actually needs, and the artifacts are what it does that work on.
163	  const why = escalationLines(reason);
164	  if (why.length) lines.push('', ...why);
165	  const del = deliveredLines(delivered);
166	  if (del.length) lines.push('', ...del);
167	  return lines.join('\n') + '\n';
168	}
169	
170	// The filing decision for one due (task, slot), given `existing` — the issues
171	// the shell fetched for this task's family (title starts with the task key),
172	// each `{ number, title, state, labels }` with state 'open' | 'closed'. Two
173	// guards:
174	//   - exactly-once per (task, slot): a state=all title match for THIS slot → skip
175	//     (makes double-runs and crash-retries safe).
176	//   - at-most-one-LIVE per task: an open family issue that is still live work
177	//     suppresses a new filing → an executor outage accumulates at most one issue
178	//     per task.
179	// Otherwise: create (the shell files it labeled with `readyLabel` — the
180	// self/fleet ready label the task's scope resolves to, default `ready-for-agent`).
181	//
182	// LIVE, NOT MERELY OPEN (#821). An escalated (`needs-human`) issue is not live
183	// work: suppressing on it would STOP the task until a person closed the issue by
184	// hand, with nothing saying the lane was shut, turning one session's death into a
185	// permanent stop. A claim - `agent-running`, or a just-filed issue not
186	// yet labeled — is someone working; a terminal is nobody, and never will be.
187	//
188	// The re-filing is bounded, because a DURABLE cause escalates every slot and would
189	// otherwise accumulate one issue per slot — the spam the guard exists to prevent.
190	// One unresolved escalation is a transient session death and must not cost the
191	// task its next slot; a second says the cause outlived a full cycle of triage, so
192	// the lane holds until a person drains it. That hold is a distinct verdict
193	// (`escalated`), not the claim verdict, so "a session is on it" and "shut,
194	// pending triage" can never look identical from outside.
195	export const NEEDS_HUMAN_HOLD = 2;
196	
197	// GitHub hands labels back as objects on the issues/search APIs and as bare
198	// strings in some fixtures; accept either.
199	const labelNames = (issue) =>
200	  (issue?.labels ?? []).map((l) => (typeof l === 'string' ? l : l?.name)).filter(Boolean);
201	
202	const isEscalated = (issue) => labelNames(issue).includes(NEEDS_HUMAN);
203	
204	export function planDispatch({ existing = [], pack, task, slotId, readyLabel = READY_LABEL, hold = NEEDS_HUMAN_HOLD }) {
205	  const title = dispatchTitle({ pack, task, slotId });
206	  const keyPrefix = `${dispatchTaskKey({ pack, task })} `;
207	  const family = existing.filter((i) => `${(i.title ?? '').trim()} `.startsWith(keyPrefix));
208	
209	  if (family.some((i) => (i.title ?? '').trim() === title)) {
210	    return { action: 'skip', reason: `dispatch issue for slot ${slotId} already exists (exactly-once)` };
211	  }
212	  const open = family.filter((i) => i.state === 'open');
213	  const live = open.find((i) => !isEscalated(i));
214	  if (live) {
215	    return { action: 'suppress', openIssue: live.number, reason: `an open dispatch issue (#${live.number}) already covers ${pack}/${task}` };
216	  }
217	  const escalated = open.filter(isEscalated);
218	  if (escalated.length >= hold) {
219	    const numbers = escalated.map((i) => `#${i.number}`).join(', ');
220	    return {
221	      action: 'suppress', escalated: true, openIssue: escalated[0].number,
222	      reason: `${escalated.length} unresolved escalations (${numbers}) on ${pack}/${task} — held for triage, not running`,
223	    };
224	  }
225	  return { action: 'create', title, label: readyLabel, reason: `no dispatch issue yet for ${pack}/${task} slot ${slotId}` };
226	}
227	
228	// The period one slot id represents, from its leading kind char (h/d/w/m). Used
229	// only for the stale-issue backstop's threshold; daily-family slots all span a
230	// day. Monthly uses 31 days so the ~2-period threshold never fires early in a
231	// long month.
232	const SLOT_PERIOD_MS = { h: 3600e3, d: 86400e3, w: 7 * 86400e3, m: 31 * 86400e3 };
233	
234	function slotPeriodMs(slotId) {
235	  return SLOT_PERIOD_MS[String(slotId ?? '')[0]] ?? null;
236	}
237	
238	// Open dispatch issues older than `factor` of their own period (~2 periods) - the scheduler's backstop when no executor session drains them. The
239	// shell adds the escalation comment + `needs-human` to each. `issue.created_at`
240	// is the ISO string GitHub returns; a title that doesn't parse (or an unknown
241	// slot kind) is never stale here.
242	//
243	// ESCALATION IS ONCE. Escalating only adds a label and leaves the issue OPEN, so
244	// an issue that already carries `needs-human` still matches every later run —
245	// and the shell re-posts the identical comment on each. Skipping the already
246	// escalated is what makes "converge to a single visible state" true rather than
247	// a state the scheduler keeps re-announcing every hour, forever.
248	//
249	// A CLAIMED issue is not this sweep's to judge either. `agent-running` means a
250	// session engaged; whether that claim is dead is `staleClaimedDispatchIssues`'s
251	// question, and it says so in its own words. Without this the two overlap on an
252	// old claimed issue, the shell's stale-first ordering wins, and the issue is
253	// told "no executor session ran it" about a session that demonstrably ran.
254	export function staleDispatchIssues(openIssues = [], now, { factor = 2 } = {}) {
255	  const nowMs = new Date(now).getTime();
256	  return openIssues.filter((issue) => {
257	    const parsed = parseDispatchTitle(issue.title);
258	    if (!parsed) return false;
259	    const names = labelNames(issue);
260	    if (names.includes(NEEDS_HUMAN) || names.includes(AGENT_RUNNING_LABEL)) return false;
261	    const period = slotPeriodMs(parsed.slotId);
262	    if (period === null) return false;
263	    return nowMs - new Date(issue.created_at).getTime() > factor * period;
264	  });
265	}
266	
267	// The escalation comment the shell posts on a stale dispatch issue.
268	export function staleEscalationComment(issue) {
269	  const parsed = parseDispatchTitle(issue.title);
270	  const which = parsed ? `${parsed.pack}/${parsed.task} (slot ${parsed.slotId})` : 'this task';
271	  return `This dispatch issue for ${which} has stayed open past ~2 of its scheduling periods without being executed — `
272	    + `no executor session ran it. Labeling \`${NEEDS_HUMAN}\` for triage.`;
273	}
274	
275	// --- re-arming a lost trigger ------------------------------------------------
276	// The label event is the executor's ONLY trigger, and a delivery can be lost: the
277	// routine was down or paused, or a session died before it claimed. The issue then
278	// sits armed forever, because the label is already applied and GitHub emits
279	// `labeled` only on a fresh add. Re-arming it - remove the ready label, add it
280	// back - emits a new event.
281	//
282	// NOTHING CALLS THESE RULES. They are kept pure and tested as the shape a
283	// legacy-cleanup rule takes in the repair phase; a caller would read the items that
284	// pass already holds. Recovery belongs in code that runs once per scheduler run,
285	// never in a sweep every triggered session runs: N sessions then race over the same
286	// N armed issues, and the claim swap cannot stop it (every session reads the work
287	// list before any claim lands) - the same dispatch run two or three times over.
288	
289	const READY_LABELS = new Set([READY_LABEL, READY_FLEET_LABEL]);
290	
291	// The ready label an issue currently carries, or null. Re-arming reapplies THIS
292	// one, so a fleet dispatch is never re-armed as a self dispatch (which would hand
293	// it to an executor whose session lacks the cross-repo reach it needs).
294	export function readyLabelOn(issue) {
295	  return labelNames(issue).find((n) => READY_LABELS.has(n)) ?? null;
296	}
297	
298	// Dispatch issues left claimed by a session that died mid-run: `agent-running`
299	// with no activity for `idleMs` (~3h). Code rather than a step each session runs,
300	// or every concurrently-triggered session would sweep and comment on the same
301	// issue; uncalled, like the re-arm.
302	//
303	// Scoped to `[claudinite-task]` dispatch issues deliberately (the title parse is
304	// what enforces it): a task may put `agent-running` on an issue IT owns — a
305	// request its pipeline has claimed, which stays claimed while its PR is in review,
306	// far longer than 3h — and only that task knows when its own claim is stale.
307	//
308	// SILENCE IS THE HOLDER'S, NOT THE ISSUE'S (#924). `livenessAt` is the shell's read
309	// of when the session that holds this claim last signed for it — its own claim or
310	// heartbeat comment, as `lastLivenessAt` reads it. Measuring from
311	// `updated_at` instead reads a dead claim as live, because any comment moves it: a
312	// losing executor letting go, a person, the task's own bookkeeping. `updated_at` is
313	// still the fallback, for an issue with no liveness signal at all and for a comment
314	// read that did not answer — a read that fails is not a verdict that the holder is
315	// dead.
316	export function staleClaimedDispatchIssues(openIssues = [], now, { idleMs = 3 * 3600e3 } = {}) {
317	  const nowMs = new Date(now).getTime();
318	  return openIssues.filter((issue) => {
319	    if (!parseDispatchTitle(issue.title)) return false;
320	    const names = labelNames(issue);
321	    if (!names.includes(AGENT_RUNNING_LABEL) || names.includes(NEEDS_HUMAN)) return false;
322	    const lastSign = issue.livenessAt ?? issue.updated_at ?? issue.created_at;
323	    return nowMs - new Date(lastSign).getTime() > idleMs;
324	  });
325	}
326	
327	// The claims a sweep must read comments for before it can judge them -
328	// `livenessAt`'s scope. Every open dispatch claim, so a candidate set narrowed by
329	// the very clock the rule stopped trusting cannot narrow it wrongly; the count is
330	// the health line's `running`, a handful.
331	export const claimedDispatchIssues = (openIssues = []) => openIssues.filter((issue) => {
332	  if (!parseDispatchTitle(issue.title)) return false;
333	  const names = labelNames(issue);
334	  return names.includes(AGENT_RUNNING_LABEL) && !names.includes(NEEDS_HUMAN);
335	});
336	
337	// The comment the shell posts when it reclaims a dead session's claim.
338	export function staleClaimComment(issue) {
339	  const parsed = parseDispatchTitle(issue.title);
340	  const which = parsed ? `${parsed.pack}/${parsed.task} (slot ${parsed.slotId})` : 'this task';
341	  return `This dispatch issue for ${which} has carried \`${AGENT_RUNNING_LABEL}\` for over 3h with no activity — `
342	    + `the executor session that claimed it never converged it. Labeling \`${NEEDS_HUMAN}\` for triage.`;
343	}
344	
345	// The open dispatch issues whose trigger evidently never landed. Re-arm only an
346	// issue that is:
347	//   - a dispatch issue (parseable title) still carrying a ready label;
348	//   - unclaimed - no `agent-running` (a live session claims before it dispatches)
349	//     and not already converged to `needs-human`;
350	//   - uncommented - the executor comments on every exit path, so a comment means
351	//     some session engaged and this is not a lost event; and
352	//   - past `graceMs` (default 20m), comfortably beyond session spin-up, so a
353	//     session already on its way is never handed a rival.
354	// A stale issue is never re-armed: it is on its way to `needs-human`, and re-arming
355	// one would loop forever.
356	export function rearmDispatchIssues(openIssues = [], now, { graceMs = 20 * 60e3 } = {}) {
357	  const nowMs = new Date(now).getTime();
358	  const stale = new Set(staleDispatchIssues(openIssues, now).map((i) => i.number));
359	  return openIssues.filter((issue) => {
360	    if (!parseDispatchTitle(issue.title)) return false;
361	    if (stale.has(issue.number)) return false;
362	    if (!readyLabelOn(issue)) return false;
363	    const names = labelNames(issue);
364	    if (names.includes(AGENT_RUNNING_LABEL) || names.includes(NEEDS_HUMAN)) return false;
365	    if ((issue.comments ?? 0) > 0) return false;
366	    return nowMs - new Date(issue.created_at).getTime() > graceMs;
367	  });
368	}
