1	// The auto-merge policy engine (docs/PRINCIPLES.md): may THIS diff land
2	// without a person? A task declares `automerge` — `'nothing'`, `'anything'`,
3	// or a list of named diff classes — and this module turns that declaration plus
4	// the branch's actual diff into a verdict. The call is arithmetic over the diff,
5	// never the session's opinion of its own work: a run cannot talk its way past a
6	// text comparison (the narrow-diff posture, generalized).
7	//
8	// WHAT A POLICY IS FOR. A policy is its author's PREDICTION of the change's
9	// shape — the folders and the kinds of file a request should touch. When the
10	// diff sits inside the prediction, nobody reads it: the code is out the door and
11	// working, and a later PR can improve it. When the diff misses the prediction,
12	// the PR parks for a person, and that park is the mechanism's purpose rather
13	// than its failure. The reviewer here is not checking that the code is perfect;
14	// they are checking the wagon is on the trail — that nothing irreversible
15	// slipped through, and that the change's footprint matches its ask (a wide diff
16	// for a small request is a lesson in separation of concerns, not a defect). So a
17	// policy is written narrow, from the predicted folders, and is never widened to
18	// fit the diff that arrived.
19	//
20	// THE VOCABULARY IS EXTENSIBLE AS DATA. Built-in diff classes live here; a pack
21	// adds its own by shipping a `merge-rules.json` beside its manifest - named
22	// path/kind/edit-shape matchers, validated at load, colliding loudly. A policy
23	// then names any rule, built-in or declared, plus the inline `under:<dir>` scope
24	// that carries its own argument, and an unknown name FAILS CLOSED: a policy this
25	// code cannot fully resolve authorizes nothing.
26	//
27	// A LIST IS A UNION, `&&` IS THE INTERSECTION. Listing two terms widens — each
28	// changed file need only be covered by one of them — so the way to say "docs,
29	// but only under this folder" is one `&&` term, never two list entries.
30	//
31	// POLICY SEMANTICS, in evaluation order:
32	//   - `'nothing'`  — never mergeable. `'anything'` — mergeable (the repo's own
33	//     delivery settings still apply downstream).
34	//   - a LIST mixes allow terms and `reject:<name>` terms. A reject matching any
35	//     changed file vetoes the whole diff; otherwise every changed file must be
36	//     covered by some allow term (first listed match wins), and every matched
37	//     rule's whole-diff constraint (e.g. "one code directory") must hold. A list
38	//     with no allow term is an authoring error, not "anything except" — spell
39	//     that as `['anything', 'reject:<name>']`.
40	//   - THE SELF-WIDENING GUARD: under a list policy, a change to the files that
41	//     define policies (`merge-rules.json`, `tasks/<name>/task.json`, this module,
42	//     its work-scope gate) is never coverable unless it is comment-only — a run
43	//     must not be able to grant itself a wider authorization than it started
44	//     with. Only the plain `'anything'` (the trusted lane: the vendored-mount
45	//     converge) can land such a change.
46	//
47	// Two judging surfaces read one resolution path: the landing lane's CLI, which a
48	// run executes before it may merge, and the `automerge-policy-scope` work check,
49	// which re-evaluates the same verdict over a branch that stamped the arming trailer.
50	
51	import path from 'node:path';
52	import { readFileSync, existsSync } from 'node:fs';
53	import { COMMENT_CHECKABLE, commentOnly } from '../../../../engine/checks/helpers/code-scanning.mjs';
54	import { FILE_CLASSES } from '../../../../engine/checks/helpers/pattern-rules.mjs';
55	import { isActive } from '../../../../engine/pack_loader/pack-registry.mjs';
56	import { AUTOMERGE_TRAILER } from '../../public/task-constants.mjs';
57	
58	export { COMMENT_CHECKABLE, commentOnly };
59	
60	export const POLICY_NOTHING = 'nothing';
61	export const POLICY_ANYTHING = 'anything';
62	
63	// The commit-message trailer a run stamps when it intends to land its own PR
64	// under a granular policy — what makes the work-scope gate self-gating: no
65	// trailer, no armed auto-merge, nothing to judge. The policy expression is the
66	// string form below (`a;b;reject:c`).
67	export { AUTOMERGE_TRAILER };
68	export const AUTOMERGE_TRAILER_RE = /^Claudinite-Automerge-Policy:[ \t]*(\S+)[ \t]*$/m;
69	
70	// --- path classification -----------------------------------------------------
71	
72	const DOC_EXTENSIONS = new Set(['.md', '.markdown', '.txt', '.rst']);
73	
74	const TEST_DIRS = new Set(['test', 'tests', '__tests__', 'spec', 'specs', 'fixtures', 'testdata']);
75	
76	// A path's kind, from the path alone: 'doc', 'test', or 'code'. Directory names
77	// are matched on whole segments (`tests/`), never on substrings, so `latest/` is
78	// not a test directory; file names are matched on the conventions every ecosystem
79	// here shares.
80	export function classifyPath(file) {
81	  const segments = file.split('/');
82	  const name = segments[segments.length - 1];
83	  if (segments.slice(0, -1).some((seg) => TEST_DIRS.has(seg) || seg.endsWith('-tests') || seg.endsWith('_tests'))) return 'test';
84	  if (/(^|[.\-_])(test|tests|spec)[.\-_]/i.test(name) || /^test_/i.test(name)) return 'test';
85	  if (DOC_EXTENSIONS.has(path.extname(name).toLowerCase())) return 'doc';
86	  return 'code';
87	}
88	
89	// --- diff entries -------------------------------------------------------------
90	
91	// One changed file with both contents: null `before` = added, null `after` =
92	// deleted. Everything below judges these, so a caller with another diff source
93	// (the work-scope context) builds the same shape.
94	export const changeKindOf = ({ before, after }) =>
95	  (before == null ? 'added' : after == null ? 'deleted' : 'modified');
96	
97	// Only line removals (and nothing else): the after-lines are an ordered
98	// subsequence of the before-lines. Deliberately order-preserving — a reorder is
99	// an edit, not a removal — and a whole-file deletion is every line removed.
100	export function removalsOnly(before, after) {
101	  return shrinkOnly(before, after, (line, original) => line === original);
102	}
103	
104	// Removals, plus in-line TRIMS: every surviving line either equals a line it
105	// replaces or is a character-subsequence of one — a line cut in half, a word
106	// struck from its middle, a truncation closed with a period the original
107	// already held. What can never pass is growth: no new line, and no character a
108	// replaced line did not already carry in order. The alignment is greedy and
109	// backtrack-free, so a pathological reshuffle can read as not-a-trim — that
110	// end fails safe (the diff parks for review).
111	export function trimsOnly(before, after) {
112	  return shrinkOnly(before, after, isCharSubsequence);
113	}
114	
115	function shrinkOnly(before, after, lineSatisfies) {
116	  if (after == null) return true;
117	  if (before == null) return false;
118	  const from = before.split('\n');
119	  const to = after.split('\n');
120	  let i = 0;
121	  for (const line of to) {
122	    while (i < from.length && !lineSatisfies(line, from[i])) i += 1;
123	    if (i === from.length) return false;
124	    i += 1;
125	  }
126	  return true;
127	}
128	
129	function isCharSubsequence(needle, hay) {
130	  let i = 0;
131	  for (const c of needle) {
132	    i = hay.indexOf(c, i);
133	    if (i === -1) return false;
134	    i += 1;
135	  }
136	  return true;
137	}
138	
139	const isCommentOnlyChange = (e) => changeKindOf(e) === 'modified' && commentOnly(e.file, e.before, e.after);
140	
141	// --- the rule registry --------------------------------------------------------
142	// A rule is `{ name, appliesTo(entry) }` plus, for the whole-diff rules, a
143	// `constraint(coveredEntries)` returning null or the reason it fails. `appliesTo`
144	// answers both roles a policy can use the name in: as an allow term it covers the
145	// files it applies to, as a `reject:` term it vetoes on them.
146	
147	// The two code-locality rules deliberately do NOT apply to a comment-only code
148	// file (mirroring narrowVerdict): a comment edit is `comment-only-changes`'
149	// business, and counting it toward the file/directory budget would fail a diff
150	// the policy's author plainly meant to allow.
151	const isRealCodeChange = (e) => classifyPath(e.file) === 'code' && !isCommentOnlyChange(e);
152	
153	export const BUILTIN_MERGE_RULES = new Map([
154	  ['doc-changes', {
155	    appliesTo: (e) => changeKindOf(e) !== 'deleted' && classifyPath(e.file) === 'doc',
156	  }],
157	  ['readme-changes', {
158	    appliesTo: (e) => changeKindOf(e) !== 'deleted' && path.basename(e.file).toLowerCase() === 'readme.md',
159	  }],
160	  ['comment-only-changes', {
161	    appliesTo: isCommentOnlyChange,
162	  }],
163	  // Every change kind, a deletion included: a policy naming this class predicted
164	  // the test tree as the change's shape, and a test file removed or renamed
165	  // inside that tree is that same shape — a rename lands as a delete beside an
166	  // add, and parking it asked a reviewer for a decision nobody made.
167	  ['test-changes', {
168	    appliesTo: (e) => classifyPath(e.file) === 'test',
169	  }],
170	  ['markdown-line-removals', {
171	    appliesTo: (e) => e.file.toLowerCase().endsWith('.md')
172	      && changeKindOf(e) !== 'added' && removalsOnly(e.before, e.after),
173	  }],
174	  // The trim superset of the rule above: whole-line removals plus in-line trims
175	  // (trimsOnly) — for a prune allowed to cut a line down, never to grow one.
176	  ['markdown-trims', {
177	    appliesTo: (e) => e.file.toLowerCase().endsWith('.md')
178	      && changeKindOf(e) !== 'added' && trimsOnly(e.before, e.after),
179	  }],
180	  ['file-additions', {
181	    appliesTo: (e) => changeKindOf(e) === 'added',
182	  }],
183	  ['generated-file-changes', {
184	    appliesTo: (e) => changeKindOf(e) !== 'deleted' && path.basename(e.file).includes('GENERATED'),
185	  }],
186	  // The language-scoped class, matching ANY change to a JavaScript-family file —
187	  // built in mostly for its `reject:` use ("nothing may touch the JS"), which is
188	  // why it applies to every change kind. Its file set is the checks engine's own
189	  // JavaScript class, so the two surfaces cannot disagree on what counts.
190	  ['javascript-changes', {
191	    appliesTo: (e) => FILE_CLASSES.javascriptFiles.test(e.file),
192	  }],
193	  ['single-file-code-changes', {
194	    appliesTo: isRealCodeChange,
195	    constraint: (covered) => {
196	      const files = [...new Set(covered.map((e) => e.file))].sort();
197	      return files.length <= 1 ? null : `code changed in ${files.length} files: ${files.join(', ')}`;
198	    },
199	  }],
200	  ['single-folder-code-changes', {
201	    appliesTo: isRealCodeChange,
202	    constraint: (covered) => {
203	      const dirs = [...new Set(covered.map((e) => path.dirname(e.file)))].sort();
204	      return dirs.length <= 1 ? null : `code changed in ${dirs.length} directories: ${dirs.join(', ')}`;
205	    },
206	  }],
207	]);
208	
209	// Composites expand into their member allow terms — `narrow-diff` is the queue's
210	// `Merge: if-narrow` shape. Stricter than narrowVerdict on purpose: a DELETED doc
211	// is not covered (deciding a document should not exist is a reviewed change),
212	// which fails toward a parked PR, never a merge.
213	export const COMPOSITE_POLICIES = new Map([
214	  ['narrow-diff', ['doc-changes', 'test-changes', 'comment-only-changes', 'single-folder-code-changes']],
215	]);
216	
217	// --- the inline path scope (`under:<dir>`) ------------------------------------
218	
219	// A rule name that carries its own argument: `under:packs/claudinite-tasks`
220	// covers every change inside that directory. It exists because a scope is
221	// usually per-request — the one folder an ad-hoc ask or a task is confined to —
222	// where a named merge-rules.json rule is per-pack and costs a commit to add.
223	//
224	// It covers any change KIND inside the directory (added, modified, deleted):
225	// "any change under this folder" reads as literally any. And it scopes rather
226	// than widens — a changed file outside the folder is covered by no allow term,
227	// so a diff that strays parks — with POLICY_SOURCES below still absolute, so a
228	// folder scope cannot reach the files that define policies even when they sit
229	// inside it.
230	export const UNDER_PREFIX = 'under:';
231	
232	const PATH_SEGMENT_RE = /^[A-Za-z0-9._-]+$/;
233	
234	// The rule an `under:<dir>` term denotes, or null when `<dir>` is not a usable
235	// repo-relative directory (absolute, empty, or carrying a `.`/`..` segment).
236	// Null is a verdict: an unresolvable scope makes the whole policy invalid, which
237	// authorizes nothing — the same fail-closed answer an unknown rule name gets.
238	export function underRule(term) {
239	  const dir = term.slice(UNDER_PREFIX.length).replace(/\/+$/, '');
240	  const segments = dir.split('/');
241	  if (!dir || segments.some((seg) => !PATH_SEGMENT_RE.test(seg) || seg === '.' || seg === '..')) return null;
242	  const prefix = `${dir}/`;
243	  return { name: term, appliesTo: (e) => e.file.startsWith(prefix) };
244	}
245	
246	// --- the `&&` intersection ----------------------------------------------------
247	
248	// A policy list is a UNION: adding a term widens what may land. `&&` is the one
249	// narrowing operator — `under:product-wiki&&doc-changes` covers a file only when
250	// every part covers it, so it reads as "docs, and only under that folder".
251	//
252	// Whitespace around it is accepted wherever a human writes one (an issue's
253	// `Automerge:` line, a task declaration) and canonicalized away by
254	// `policyExpression`, so what rides the commit trailer stays one whitespace-free
255	// token. `&` is not a legal character in a rule name or an `under:` path, so the
256	// operator can never be read as part of a term.
257	export const CONJUNCTION = '&&';
258	
259	const conjunctionParts = (term) => term.split(CONJUNCTION).map((p) => p.trim());
260	
261	// --- pack-declared rules (merge-rules.json) -----------------------------------
262	
263	export const MERGE_RULES_FILE = 'merge-rules.json';
264	
265	const RULE_NAME_RE = /^[a-z0-9]+(-[a-z0-9]+)*$/;
266	const DECLARED_KEYS = ['name', 'pathMatching', 'excludePathMatching', 'changeKinds', 'editShape', 'coversMountPolicySources'];
267	const CHANGE_KINDS = ['added', 'modified', 'deleted'];
268	const EDIT_SHAPES = ['any', 'removals-only', 'comment-only'];
269	
270	// Regex-as-string in the `/body/flags` form declared checks already use. The
271	// checks engine's compiler is private, so the same parse is repeated here.
272	function compileRegex(raw, where) {
273	  const m = /^\/(.*)\/([a-z]*)$/s.exec(String(raw));
274	  if (!m) throw new Error(`${where}: ${JSON.stringify(raw)} is not a /pattern/ regex string`);
275	  return new RegExp(m[1], m[2]);
276	}
277	
278	// One declared rule compiled into the registry shape. Every key is validated and
279	// `changeKinds`/`editShape` are REQUIRED — a matcher whose reach is defaulted is
280	// a matcher nobody decided (the corpus' explicit-over-default rule).
281	export function compileDeclaredRule(spec, where) {
282	  if (spec === null || typeof spec !== 'object' || Array.isArray(spec)) {
283	    throw new Error(`${where}: a merge rule is an object, not ${JSON.stringify(spec)}`);
284	  }
285	  for (const key of Object.keys(spec)) {
286	    if (!DECLARED_KEYS.includes(key)) {
287	      throw new Error(`${where}: "${key}" is not a merge-rule key — the vocabulary is: ${DECLARED_KEYS.join(', ')}`);
288	    }
289	  }
290	  if (typeof spec.name !== 'string' || !RULE_NAME_RE.test(spec.name)) {
291	    throw new Error(`${where}: a merge rule needs a kebab-case "name"`);
292	  }
293	  const pathMatching = compileRegex(spec.pathMatching, `${where} (${spec.name}).pathMatching`);
294	  const exclude = spec.excludePathMatching === undefined
295	    ? null : compileRegex(spec.excludePathMatching, `${where} (${spec.name}).excludePathMatching`);
296	  if (!Array.isArray(spec.changeKinds) || !spec.changeKinds.length
297	      || spec.changeKinds.some((k) => !CHANGE_KINDS.includes(k))) {
298	    throw new Error(`${where} (${spec.name}): "changeKinds" is a non-empty subset of ${CHANGE_KINDS.join(', ')}`);
299	  }
300	  if (!EDIT_SHAPES.includes(spec.editShape)) {
301	    throw new Error(`${where} (${spec.name}): "editShape" must be one of ${EDIT_SHAPES.join(', ')} — declared, never defaulted`);
302	  }
303	  // The one key that may relax the self-widening guard, and only for files under
304	  // the VENDORED MOUNT (see POLICY_SOURCES below): declaring it is an owner
305	  // saying "this task may rewrite the mount, policy definitions included" — the
306	  // adoption/converge grant. `true` only, so it cannot be half-declared.
307	  if (spec.coversMountPolicySources !== undefined && spec.coversMountPolicySources !== true) {
308	    throw new Error(`${where} (${spec.name}): "coversMountPolicySources" takes only \`true\` — omit it otherwise`);
309	  }
310	  return {
311	    name: spec.name,
312	    coversMountPolicySources: spec.coversMountPolicySources === true,
313	    appliesTo(e) {
314	      if (!pathMatching.test(e.file) || (exclude && exclude.test(e.file))) return false;
315	      if (!spec.changeKinds.includes(changeKindOf(e))) return false;
316	      if (spec.editShape === 'removals-only') return changeKindOf(e) !== 'added' && removalsOnly(e.before, e.after);
317	      if (spec.editShape === 'comment-only') return isCommentOnlyChange(e);
318	      return true;
319	    },
320	  };
321	}
322	
323	// The merge rules the ACTIVE packs declare, keyed by name. `packs` are discovered
324	// pack objects (each with `.dir`), `config` the normalized repo config — the pair
325	// both judging surfaces already hold. A broken declaration or a name collision is
326	// an ERROR entry, never a silent drop: a policy naming the broken rule must fail
327	// closed, and the error text is what gets it fixed.
328	export function declaredMergeRules(packs, config) {
329	  const rules = new Map();
330	  const errors = [];
331	  for (const pack of (packs ?? []).filter((p) => p.dir && isActive(p, config))) {
332	    const file = path.join(pack.dir, MERGE_RULES_FILE);
333	    if (!existsSync(file)) continue;
334	    const where = `${pack.id}/${MERGE_RULES_FILE}`;
335	    let specs;
336	    try {
337	      specs = JSON.parse(readFileSync(file, 'utf8'));
338	      if (!Array.isArray(specs)) throw new Error('the file must hold an array of rule objects');
339	    } catch (e) {
340	      errors.push(`${where}: ${e.message}`);
341	      continue;
342	    }
343	    for (const spec of specs) {
344	      try {
345	        const rule = compileDeclaredRule(spec, where);
346	        if (BUILTIN_MERGE_RULES.has(rule.name) || COMPOSITE_POLICIES.has(rule.name) || rules.has(rule.name)) {
347	          throw new Error(`rule name "${rule.name}" is already taken — merge-rule names are one flat namespace`);
348	        }
349	        rules.set(rule.name, rule);
350	      } catch (e) {
351	        errors.push(e.message.startsWith(where) ? e.message : `${where}: ${e.message}`);
352	      }
353	    }
354	  }
355	  return { rules, errors };
356	}
357	
358	// --- policy parsing -----------------------------------------------------------
359	
360	const TERM_NAME_RE = /^(under:\S+|[a-z0-9]+(-[a-z0-9]+)*)$/;
361	
362	// A policy, normalized from any surface it rides — the declaration's string or
363	// array, the item's `Merge:` field, the commit trailer's `a;b;reject:c` — into
364	// { kind: 'nothing' | 'anything' } or { kind: 'rules', allow, reject } or
365	// { kind: 'invalid', reason }. Invalid is a verdict-shaped answer on purpose:
366	// every consumer treats it as "authorizes nothing", loudly.
367	export function normalizePolicy(raw) {
368	  if (raw == null) return { kind: POLICY_NOTHING };
369	  const terms = Array.isArray(raw)
370	    ? raw.map((t) => String(t).trim())
371	    : String(raw).trim().split(';').map((t) => t.trim());
372	  if (terms.length === 1) {
373	    const one = terms[0].toLowerCase();
374	    if (one === POLICY_NOTHING || one === '') return { kind: POLICY_NOTHING };
375	    if (one === POLICY_ANYTHING) return { kind: POLICY_ANYTHING };
376	    // The queue's historical spellings for its one pre-policy authorization.
377	    if (one === 'if-narrow' || one === 'yes' || one === 'true') return normalizePolicy(['narrow-diff']);
378	  }
379	  const allow = [];
380	  const reject = [];
381	  for (const term of terms) {
382	    const isReject = term.startsWith('reject:');
383	    const parts = conjunctionParts(isReject ? term.slice('reject:'.length) : term);
384	    for (const part of parts) {
385	      if (!TERM_NAME_RE.test(part)) {
386	        return { kind: 'invalid', reason: `"${term}" is not a policy term (rule names or under:<dir>, joined with && and optionally reject:-prefixed)` };
387	      }
388	      if (part.startsWith(UNDER_PREFIX) && !underRule(part)) {
389	        return { kind: 'invalid', reason: `"${part}" names no usable repo-relative directory — spell it under:packs/some-pack` };
390	      }
391	    }
392	    // A composite is itself a union, so intersecting one is ambiguous, and the
393	    // whole-policy words mean nothing narrowed: both are authoring errors.
394	    if (parts.length > 1) {
395	      const notIntersectable = parts.find((p) => COMPOSITE_POLICIES.has(p) || p === POLICY_ANYTHING || p === POLICY_NOTHING);
396	      if (notIntersectable) {
397	        return { kind: 'invalid', reason: `"${notIntersectable}" cannot sit in an && term — intersect specific rules` };
398	      }
399	    }
400	    const name = parts.join(CONJUNCTION);
401	    if (isReject) {
402	      if (COMPOSITE_POLICIES.has(name)) return { kind: 'invalid', reason: `"${term}" rejects a composite — name the specific rules to reject` };
403	      reject.push(name);
404	    } else if (name === POLICY_ANYTHING) {
405	      allow.push(name);
406	    } else if (name === POLICY_NOTHING) {
407	      return { kind: 'invalid', reason: `"nothing" cannot sit in a rule list — it is a whole policy of its own` };
408	    } else {
409	      allow.push(...(COMPOSITE_POLICIES.get(name) ?? [name]));
410	    }
411	  }
412	  if (!allow.length) {
413	    return { kind: 'invalid', reason: 'the policy lists no allow term — "anything except X" is spelled ["anything", "reject:X"]' };
414	  }
415	  return { kind: 'rules', allow: [...new Set(allow)], reject: [...new Set(reject)] };
416	}
417	
418	// The string form of a declared policy — what rides the commit trailer and the
419	// worker's CLI invocation. Inverse of normalizePolicy for every legal value, and
420	// the one place whitespace around `&&` is collapsed, which is what keeps the
421	// stamped trailer a single whitespace-free token.
422	export const policyExpression = (policy) =>
423	  (Array.isArray(policy) ? policy : String(policy ?? POLICY_NOTHING).split(';'))
424	    .map((t) => conjunctionParts(String(t).trim()).join(CONJUNCTION))
425	    .join(';');
426	
427	// --- the verdict --------------------------------------------------------------
428	
429	// The files no granular policy may cover except as comment-only edits: the
430	// sources the policy machinery itself is read from. Whatever an allow rule says,
431	// a run authorized by a list must not be able to rewrite what it is authorized
432	// to do. (`'anything'` — the vendored-converge lane — is deliberately exempt:
433	// the mount refresh replaces these files wholesale, and that lane's trust is the
434	// repo's delivery setting, not a diff class.)
435	//
436	// One narrow relaxation: such a file UNDER THE VENDORED MOUNT may be covered by
437	// a declared rule carrying `coversMountPolicySources` — the shape an adoption
438	// re-vendor has, where policy files arrive canon-authored inside the pack trees
439	// it copies. The flag rides merge-rules.json, which is itself guarded and
440	// owner-committed, so a run cannot grant it to itself; repo-owned policy
441	// sources (everything outside the mount) stay absolute.
442	const POLICY_SOURCES = /(^|\/)(merge-rules\.json|merge-policy\.mjs|workRules\/automerge-policy-scope\.mjs|tasks\/[^/]+\/task\.json)$/;
443	const VENDORED_MOUNT = /^\.claudinite\/shared\//;
444	
445	// The whole verdict over a diff. `entries` are `{ file, before, after }` (null
446	// side = added/deleted); `declaredRules` a Map from declaredMergeRules, with its
447	// `errors` passed through so a broken declaration fails any policy that names
448	// the broken pack's rule set. Returns { mergeable, why, files, problems }:
449	// `files` carries one line per changed file (its covering rule, or its
450	// violation), `problems` each refusal as { file, what } — file null for a
451	// whole-diff refusal — because a run that parks has to say what it parked over.
452	export function policyVerdict({ policy, entries, declaredRules = new Map(), ruleErrors = [] }) {
453	  const refuse = (problems, files = []) => ({
454	    mergeable: false, why: problems.map((p) => p.what).join('; '), files, problems,
455	  });
456	  const norm = normalizePolicy(policy);
457	  if (norm.kind === 'invalid') return refuse([{ file: null, what: `invalid policy: ${norm.reason}` }]);
458	  if (norm.kind === POLICY_NOTHING) {
459	    return refuse([{ file: null, what: 'the policy authorizes nothing to auto-merge' }]);
460	  }
461	  if (norm.kind === POLICY_ANYTHING) {
462	    return { mergeable: true, why: 'the policy authorizes any diff (the repo\'s delivery settings still apply)', files: [], problems: [] };
463	  }
464	  if (!entries.length) {
465	    return refuse([{ file: null, what: 'this branch changes nothing against the base — there is nothing to merge' }]);
466	  }
467	
468	  const resolveOne = (name) => (name.startsWith(UNDER_PREFIX)
469	    ? underRule(name)
470	    : BUILTIN_MERGE_RULES.get(name) ?? declaredRules.get(name) ?? null);
471	  // An `&&` term is one rule that every part must agree on — for coverage and
472	  // for the whole-diff constraints alike. It deliberately carries no
473	  // `coversMountPolicySources`: that grant belongs to the declared rule that was
474	  // committed with it, never to an expression composed around it.
475	  const resolve = (name) => {
476	    if (!name.includes(CONJUNCTION)) return resolveOne(name);
477	    const parts = name.split(CONJUNCTION).map(resolveOne);
478	    if (parts.some((r) => !r)) return null;
479	    return {
480	      name,
481	      appliesTo: (e) => parts.every((r) => r.appliesTo(e)),
482	      constraint: (covered) => parts.map((r) => r.constraint?.(covered) ?? null).find(Boolean) ?? null,
483	    };
484	  };
485	  const unknown = [...norm.allow, ...norm.reject].filter((n) => n !== POLICY_ANYTHING && !resolve(n));
486	  if (unknown.length) {
487	    const errs = ruleErrors.length ? ` (rule declarations also failed to load: ${ruleErrors.join('; ')})` : '';
488	    return refuse([{ file: null, what: `unresolved rule name(s): ${unknown.join(', ')} — an unknown rule authorizes nothing${errs}` }]);
489	  }
490	
491	  const files = [];
492	  const problems = [];
493	  const coveredBy = new Map(); // allow name -> entries it covered
494	  for (const entry of entries) {
495	    const { file } = entry;
496	    if (POLICY_SOURCES.test(file) && !isCommentOnlyChange(entry)) {
497	      const mountCoverer = VENDORED_MOUNT.test(file)
498	        && norm.allow.find((n) => resolve(n)?.coversMountPolicySources && resolve(n).appliesTo(entry));
499	      if (!mountCoverer) {
500	        files.push({ file, verdict: 'policy-source' });
501	        problems.push({ file, what: `${file} defines auto-merge policy itself — no granular policy may change it` });
502	        continue;
503	      }
504	      // Exempted: it falls through to the ordinary reject/coverage flow below,
505	      // so a reject term still vetoes it and the flagged rule still has to
506	      // cover it on its own terms.
507	    }
508	    const rejectedBy = norm.reject.find((n) => resolve(n).appliesTo(entry));
509	    if (rejectedBy) {
510	      files.push({ file, verdict: `rejected:${rejectedBy}` });
511	      problems.push({ file, what: `${file} matches reject:${rejectedBy}` });
512	      continue;
513	    }
514	    const coverer = norm.allow.find((n) => n === POLICY_ANYTHING || resolve(n).appliesTo(entry));
515	    if (coverer === undefined) {
516	      files.push({ file, verdict: 'uncovered' });
517	      problems.push({ file, what: `${file} (${changeKindOf(entry)} ${classifyPath(entry.file)}) is covered by no allow term` });
518	      continue;
519	    }
520	    files.push({ file, verdict: `covered:${coverer}` });
521	    if (!coveredBy.has(coverer)) coveredBy.set(coverer, []);
522	    coveredBy.get(coverer).push(entry);
523	  }
524	  for (const [name, covered] of coveredBy) {
525	    const failed = resolve(name)?.constraint?.(covered) ?? null;
526	    if (failed) problems.push({ file: null, what: `${name}: ${failed}` });
527	  }
528	
529	  return problems.length
530	    ? refuse(problems, files)
531	    : { mergeable: true, why: `every changed file is covered (${[...coveredBy.keys()].join(', ')})`, files, problems: [] };
532	}
533

